      },
      {
        "group": "건강",
        "class_code": "HH_REPRO",
        "category": "2",
        "raw": "생식독성 : 구분 2",
        "line": "p1:L18"
      },
      {
        "group": "건강",
        "class_code": "HH_STOT_SE",
        "category": "3",
        "effect": "마취작용",
        "raw": "특정표적장기 독성(1 회 노출) : 구분 3(마취작용)",
        "line": "p1:L19"
      },
      {
        "group": "건강",
        "class_code": "HH_STOT_RE",
        "category": "2",
        "raw": "특정표적장기 독성(반복 노출) : 구분 2",
        "line": "p1:L20"
      },
      {
        "group": "건강",
        "class_code": "HH_ASPIRATION",
        "category": "1",
        "raw": "흡인 유해성 : 구분 1",
        "line": "p1:L21"
      }
    ],
    "signal_word": "위험",
    "pictograms": [
      {
        "code": "GHS02"
      },
      {
        "code": "GHS08"
      },
      {
        "code": "GHS07"
      }
    ],
    "h_statements": [
      {
        "code": "H225",
        "text": "고인화성 액체 및 증기",
        "line": "p2:L4"
      },
      {
        "code": "H304",
        "text": "삼켜서 기도로 유입되면 치명적일 수 있음",
        "line": "p2:L5"
      },
      {
        "code": "H315",
        "text": "피부에 자극을 일으킴",
        "line": "p2:L6"
      },
      {
        "code": "H336",
        "text": "졸음 또는 현기증을 일으킬 수 있음",
        "line": "p2:L7"
      },
      {
        "code": "H361",
        "text": "태아 또는 생식능력에 손상을 일으킬 것으로 의심됨",
        "line": "p2:L8"
      },
      {
        "code": "H373",
        "text": "장기간 또는 반복노출 되면 신체 중 장기에 손상을 일으킬 수 있음",
        "line": "p2:L9"
      }
    ],
    "p_statements": [
      {
        "code": "P201",
        "type": "예방",
        "text": "사용 전 취급 설명서를 확보하시오.",
        "line": "p2:L12"
      },
      {
        "code": "P202",
        "type": "예방",
        "text": "모든 안전 예방조치 문구를 읽고 이해하기 전에는 취급하지 마시오.",
        "line": "p2:L13"
      },
      {
        "code": "P210",
        "type": "예방",
        "text": "열·스파크·화염·고열로부터 멀리하시오 - 금연",
        "line": "p2:L14"
      },
      {
        "code": "P233",
        "type": "예방",
        "text": "용기를 단단히 밀폐하시오.",
        "line": "p2:L15"
      },
      {
        "code": "P240",
        "type": "예방",
        "text": "용기·수용설비를 접지·접합시키시오.",
        "line": "p2:L16"
      },
      {
        "code": "P241",
        "type": "예방",
        "text": "폭발 방지용 전기·환기·조명·장비를 사용하시오",
        "line": "p2:L17"
      },
      {
        "code": "P242",
        "type": "예방",
        "text": "스파크가 발생하지 않는 도구를 사용하시오.",
        "line": "p2:L18"
      },
      {
        "code": "P243",
        "type": "예방",
        "text": "정전기 방지 조치를 취하시오.",
        "line": "p2:L19"
      },
      {
        "code": "P260",
        "type": "예방",
        "text": "(분진·흄·가스·미스트·증기·스프레이)를(을) 흡입하지 마시오.",
        "line": "p2:L20"
      },
      {
        "code": "P261",
        "type": "예방",
        "text": "(분진·흄·가스·미스트·증기·스프레이)의 흡입을 피하시오.",
        "line": "p2:L21"
      },
      {
        "code": "P264",
        "type": "예방",
        "text": "취급 후에는 손을 철저히 씻으시오.",
        "line": "p2:L22"
      },
      {
        "code": "P271",
        "type": "예방",
        "text": "옥외 또는 환기가 잘 되는 곳에서만 취급하시오.",
        "line": "p2:L23"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "(보호장갑·보호의·보안경·안면보호구)를(을) 착용하시오.",
        "line": "p2:L24"
      },
      {
        "code": "P301+P310",
        "type": "대응",
        "text": "삼켰다면 즉시 의료기관(의사)의 도움을 받으시오",
        "line": "p2:L26"
      },
      {
        "code": "P302+P352",
        "type": "대응",
        "text": "피부에 묻으면 다량의 물과 비누로 씻으시오.",
        "line": "p2:L27"
      },
      {
        "code": "P303+P361+P353",
        "type": "대응",
        "text": "피부(또는 머리카락)에 묻으면 오염된 모든 의복은 벗거나 제거하시오. 피부를 물로 씻으시오/샤워하시오.",
        "line": "p2:L28"
      },
      {
        "code": "P304+P340",
        "type": "대응",
        "text": "흡입하면 신선한 공기가 있는 곳으로 옮기고 호흡하기 쉬운 자세로 안정을 취하시오.",
        "line": "p2:L30"
      },
      {
        "code": "P308+P313",
        "type": "대응",
        "text": "노출 또는 접촉이 우려되면 의학적인 조언·주의를 받으시오.",
        "line": "p2:L32"
      },
      {
        "code": "P312",
        "type": "대응",
        "text": "불편함을 느끼면 의료기관(의사)의 진찰을 받으시오.",
        "line": "p2:L33"
      },
      {
        "code": "P314",
        "type": "대응",
        "text": "불편함을 느끼면 의학적인 조치·조언을 구하시오.",
        "line": "p2:L34"
      },
      {
        "code": "P321",
        "type": "대응",
        "text": "필요한 처치를 하시오.",
        "line": "p3:L2"
      },
      {
        "code": "P331",
        "type": "대응",
        "text": "토하게 하지 마시오.",
        "line": "p3:L3"
      },
      {
        "code": "P332+P313",
        "type": "대응",
        "text": "피부 자극이 생기면 의학적인 조언·주의를 받으시오.",
        "line": "p3:L4"
      },
      {
        "code": "P362+P364",
        "type": "대응",
        "text": "오염된 의복은 벗고 다시 사용 전 세탁하시오.",
        "line": "p3:L5"
      },
      {
        "code": "P370+P378",
        "type": "대응",
        "text": "화재 시 불을 끄기 위해 적절한 소화기를 사용하시오.",
        "line": "p3:L6"
      },
      {
        "code": "P403+P233",
        "type": "저장",
        "text": "용기는 환기가 잘 되는 곳에 단단히 밀폐하여 저장하시오.",
        "line": "p3:L8"
      },
      {
        "code": "P403+P235",
        "type": "저장",
        "text": "환기가 잘 되는 곳에 보관하고 저온으로 유지하시오.",
        "line": "p3:L9"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "잠금장치가 있는 저장장소에 저장하시오",
        "line": "p3:L10"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "관련 법규에 명시된 내용에 따라 내용물·용기를 폐기하시오.",
        "line": "p3:L12"
      }
    ],
    "other_hazards": [
      {
        "value": "자료 없음.",
        "line": "p3:L14"
      }
    ]
  ,
    "nfpa": {
      "health": 3,
      "fire": 0,
      "reactivity": 2
    }
  ,
    "lines": {
      "signal_word": "p1:L24",
      "pictograms": "p1:L23",
      "nfpa": "p1:L24"
    }
  }
,
  "narratives": [
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "가. 유해.위험성 분류 :",
      "start":  "p1:L15",
      "end":    "p1:L21"
    },
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "나. 예방조치 문구를 포함한 경고 표지 항목",
      "start":  "p1:L22",
      "end":    "p3:L12"
    },
    {
      "item_code": "S2_LABEL_NOTE",
      "title_raw": "다. 유해, 위험성 분류기준에 포함되지 않는 기타 유해, 위험성 :",
      "start":  "p3:L13",
      "end":    "p3:L14"
    }
  ]
,
  "extras": []
}

